	"gift_premium_subtitle": "Подаруйте %2$s річну передплату %1$s за %3$s. Коли ви проведете оплату, цей користувач отримає сповіщення про те, що ви надіслали йому подарунок.",
	"gift_premium_terms_footer": "Кошти за оформлення подарункової підписки стягуються в момент покупки й не підлягають поверненню. Це одноразова передплата, яка не підлягає заміні, не комбінується та не має грошової вартості. Термін її дії розпочнеться після того, як X розгляне замовлення та призначить передплату одержувачу, який повинен буде прийняти наші %1$s та політики. Якщо одержувач не відповідає якимось вимогам або якщо він скасує передплату чи відхилить наші умови та політики, подарунок не підлягає обміну чи поверненню. Можуть стягуватися податки. Умови можуть змінюватися. %2$s",
