	"go_to_twitter": "Перейти на x.com",
	"golive__tip_broadcaster_1": "<b>ПОРАДА.</b> Дякуємо за пряму трансляцію! Вітайтеся з людьми, які приєднуються.",
	"golive__tip_broadcaster_10": "<b>ПОРАДА.</b> Дякуємо за пряму трансляцію в Х! ≺3",
	"golive__tip_broadcaster_2": "<b>ПОРАДА.</b> Спробуйте звертатися по імені до глядачів, які приєднуються до вашої трансляції. Вони будуть у захваті.",
	"golive__tip_broadcaster_3": "<b>ПОРАДА.</b> Трансляція має тривати не менше кількох хвилин, щоб люди встигли вас знайти.",
	"golive__tip_broadcaster_4": "<b>ПОРАДА.</b> Щоб створити невимушену атмосферу, запитайте своїх глядачів, звідки вони.",
	"golive__tip_broadcaster_5": "<b>TIP:</b> Дякуйте глядачам за вибір вашої трансляції та відповідайте на їхні коментарі, щоб вони не відключалися.",
	"golive__tip_broadcaster_6": "<b>ПОРАДА.</b> Якщо під час трансляції розірветься зв’язок, перейдіть у місце з кращим сигналом.",
	"golive__tip_broadcaster_7": "<b>ПОРАДА.</b> Попросіть глядачів підписатися на вас, щоб вони отримали сповіщення про вашу наступну трансляцію.",
	"golive__tip_broadcaster_8": "<b>ПОРАДА.</b> Привітайтеся на самому початку прямої трансляції. Це дуже сподобається тим, хто дивитиметься її пізніше.",
	"golive__tip_broadcaster_9": "<b>ПОРАДА.</b> Подякуйте своїм глядачам за те, що вони дивилися трансляцію, перш ніж завершувати її.",
	"golive__tip_pre_broadcast_1": "<b>ПОРАДА.</b> Напишіть назву, перш ніж починати трансляцію, щоб її було легше знайти.",
	"golive__tip_pre_broadcast_2": "<b>ПОРАДА.</b> Описова назва допоможе людям зрозуміти, про що ваша трансляція.",
	"golive__tip_pre_broadcast_3": "<b>ПОРАДА.</b> Потрібні ідеї? Проведіть екскурсію, покажіть свій талант або поговоріть на цікаву тему.",
	"golive__tip_pre_broadcast_4": "<b>ПОРАДА.</b> Перш ніж починати пряму трансляцію, перевірте, чи сигнал телефону достатньо сильний.",
	"golive__tip_pre_broadcast_5": "<b>ПОРАДА.</b> Додайте до назви хештег, щоб вашу трансляцію було легше знайти.",
	"golive__tip_pre_broadcast_6": "<b>ПОРАДА.</b> Наразі це всі наші поради. Дякуємо за пряму трансляцію Х!",
