	"identity_education_cancel": "Не зараз",
	"identity_education_conditions": "Я дозволяю X і Au10tix використовувати зображення мого посвідчення особи й моє селфі, у тому числі одержані з них біометричні дані, з метою підтвердження моєї особи й підтримання безпеки X, зокрема для захисту від самозванців. Au10tix може зберігати такі дані до 30 днів. {{}}Докладніше{{}}",
	"identity_education_conditions_age_verification": "Я дозволяю X та Persona використовувати зображення мого посвідчення особи та мою фотографію для перевірки мого віку. Фотографію не буде збережено. X та xAI можуть зберігати інформацію про вік. {{}}Докладніше{{}}",
	"identity_education_conditions_eea": "Я дозволяю Х передавати компанії Au10tix зображення мого посвідчення особи, зокрема біометричні дані, а також особисті дані з мого профілю з метою підтвердження особи. Я також дозволяю Х зберігати зображення мого посвідчення особи, зокрема біометричні дані, протягом 30 днів і використовувати їх разом із даними з мого профілю для підтримання безпеки, зокрема для захисту від самозванців. {{}}Детальніше{{}}",
	"identity_education_conditions_persona_vendor": "Я дозволяю X і Persona використовувати зображення мого посвідчення особи й моє селфі, зокрема одержані з них біометричні дані, для підтвердження моєї особи, а також із метою підтримання безпеки X, запобігання шахрайству й здійснення оплати. Persona може зберігати такі дані до 30 днів. X може зберігати моє повне ім’я, адресу й захешований номер посвідчення особи протягом усього терміну моєї передплати X Premium. {{}}Докладніше{{}}",
