	"payment_funds_insurance_footer_secondary_text": "Додаткову інформацію про страхування FDIC та категорії володіння рахунками можна знайти ﻿тут﻿.",
	"payment_funds_insurance_footer_text": "Ваші депозити зберігаються в банку Cross River, який є членом FDIC, і застраховані FDIC на суму до 250 000 дол. США на одну фізичну та одну юридичну особу для всіх рахунків у кожній категорії володіння рахунками, що ведуться в банку (сукупно), зокрема рахунків, що ведуться в представницькій формі.",
	"payment_funds_insurance_footer_text_format": "Ваші депозити зберігаються в банку Cross River («Банк»), який є членом FDIC, і застраховані FDIC на суму до {amount} дол. США на одну фізичну та одну юридичну особу для всіх рахунків у кожній категорії володіння рахунками, що ведуться в Банку (сукупно), зокрема рахунків, що ведуться в представницькій формі.",
	"payment_funds_insurance_sweep_disclaimer": "Депозити зберігаються в банку Cross River, який є членом FDIC, та ﻿інших установах, застрахованих FDIC﻿. Для застосування наскрізного страхування депозитів мають бути виконані ﻿певні умови﻿. X Payments LLC не є банком, застрахованим FDIC. Страхування депозитів поширюється лише на випадки банкрутства застрахованих банків.",
	"payment_funds_insurance_sweep_presentation": "Ваші депозити автоматично реєструються в програмі X Cash Sweep, яка надає доступ до сукупного страхового покриття від FDIC на суму до 10 млн дол. США (з урахуванням певних обмежень). ﻿Докладніше",
