	"ps__report_guest_dialog_abusive_behavior_message": "Якщо, на вашу думку, цей гість когось переслідує, залякує або змушує мовчати, торкніться нижче.",
	"ps__report_guest_dialog_child_safety_message": "Якщо, на вашу думку, цей гість поширює матеріали, що становлять ризик для дітей, торкніться нижче.",
	"ps__report_guest_dialog_dont_like_message": "\"Ви можете заблокувати користувача, трансляції якого більше не хочете бачити. Ви й надалі бачитимете заблокованих користувачів, коли вони будуть гостями трансляцій.\n\nУ разі блокування до Periscope не буде надіслано скаргу на @%1$s.\"",
	"ps__report_guest_dialog_hateful_conduct_message": "Якщо, на вашу думку, цей гість розпалює ненависть до захищеної категорії осіб (наприклад, осіб певної раси, релігії, гендеру, орієнтації чи осіб з інвалідністю), торкніться нижче.",
	"ps__report_guest_dialog_private_information_message": "Якщо, на вашу думку, цей гість оприлюднює особисту інформацію, торкніться нижче.",
	"ps__report_guest_dialog_self_harm_message": "Якщо, на вашу думку, цей гість має намір учинити самогубство чи заподіяти собі шкоду або заохочує когось до цього, торкніться нижче.",
	"ps__report_guest_dialog_sexual_content_message": "Якщо, на вашу думку, цей гість поширює непристойні сексуальні матеріали, як-от порнографію, торкніться нижче.",
	"ps__report_guest_dialog_violence_message": "Якщо, на вашу думку, цей гість прямо погрожує насильством, зокрема фізичною розправою або психологічним тиском, торкніться нижче.",
