	"ps__tip_broadcaster_1": "<b>ПОРАДА.</b> Дякуємо за трансляцію! Не забудьте привітатися з людьми, які приєднуються.",
	"ps__tip_broadcaster_11": "<b>ПОРАДА.</b> Дякуємо за трансляцію в Periscope! ≺3",
	"ps__tip_broadcaster_2": "<b>ПОРАДА.</b> Спробуйте звертатися до глядачів по імені – вони будуть у захваті!",
	"ps__tip_broadcaster_3": "<b>ПОРАДА.</b> Трансляція має тривати не менше кількох хвилин, щоб люди встигли вас знайти.",
	"ps__tip_broadcaster_4": "<b>ПОРАДА.</b> Запитайте своїх глядачів, звідки вони. Це чудовий спосіб створити невимушену атмосферу.",
	"ps__tip_broadcaster_5": "<b>ПОРАДА.</b> Дякуйте глядачам за вибір вашої трансляції та відповідайте на їхні коментарі, щоб вони не відключалися.",
	"ps__tip_broadcaster_6": "<b>ПОРАДА.</b> Якщо під час трансляції розірветься зв’язок, перейдіть у місце з кращим сигналом.",
	"ps__tip_broadcaster_7": "<b>ПОРАДА.</b> Попросіть глядачів підписуватися на вас, щоб вони отримували сповіщення, коли ви починаєте трансляцію.",
	"ps__tip_broadcaster_8": "<b>ПОРАДА.</b> Привітайтеся на самому початку трансляції. Це дуже сподобається глядачам повторів.",
	"ps__tip_broadcaster_9": "<b>ПОРАДА.</b> Подякуйте своїм глядачам за перегляд, перш ніж завершувати трансляцію.",
	"ps__tip_pre_broadcast_1": "<b>ПОРАДА.</b> Напишіть назву, перш ніж починати трансляцію, щоб приєдналися люди зі схожими інтересами!",
	"ps__tip_pre_broadcast_2": "<b>ПОРАДА.</b> Описова назва допоможе людям зрозуміти, про що ваша трансляція.",
	"ps__tip_pre_broadcast_3": "<b>ПОРАДА.</b> Потрібні ідеї? Проведіть екскурсію, покажіть свій талант або поговоріть на цікаву тему.",
	"ps__tip_pre_broadcast_4": "<b>ПОРАДА.</b> Перш ніж починати трансляцію, перевірте, чи сигнал телефону достатньо сильний.",
	"ps__tip_pre_broadcast_5": "<b>ПОРАДА.</b> Поширюйте свої трансляції в X, щоб здобути більше глядачів.",
	"ps__tip_pre_broadcast_6": "<b>ПОРАДА.</b> Для ваших читачів, яких ви також читаєте, можна вести приватну трансляцію.",
	"ps__tip_pre_broadcast_8": "<b>ПОРАДА.</b> Додайте до назви відповідний хештег, щоб вашу трансляцію було легше знайти.",
	"ps__tip_pre_broadcast_9": "<b>ПОРАДА.</b> Наразі це всі наші поради. Дякуємо, що користуєтеся Periscope!",
	"ps__tip_viewer_1": "<b>ПОРАДА.</b> Ви приєднались одним із перших, напишіть коментар і привітайтеся!",
	"ps__tip_viewer_2": "<b>ПОРАДА.</b> Напишіть коментар, щоб сповістити <b>%1$s</b> про свою присутність!",
	"ps__tip_viewer_3": "<b>ПОРАДА.</b> Сповістіть <b>%1$s</b>, звідки ви дивитеся трансляцію!",
	"ps__tip_viewer_4": "<b>ПОРАДА.</b> Привітайтеся, щоб завести розмову з <b>%1$s</b> та іншими глядачами.",
	"ps__toast_broadcast_notify_followers": "Ми сповістили ваших читачів, що ви приєдналися до трансляції в ролі гостя",
